# Expected values below are synthetic hand-calculated trapezoids, independent of app functions.
source('apps/pk-desktop/pkapp.R')
core <- environment(pkapp_open)
scenarios <- 0L
check <- function(name, expr) { force(expr); scenarios <<- scenarios+1L; cat(sprintf('PASS %02d %s\n',scenarios,name)) }
eq <- function(x,y) stopifnot(isTRUE(all.equal(x,y,tolerance=1e-11,check.attributes=FALSE)))
refused <- function(expr) { msg<-tryCatch({force(expr);NULL},error=conditionMessage); stopifnot(is.character(msg),nzchar(msg)); invisible(msg) }
s <- list(id='ID',time='TIME',concentration='CONC',concentration_unit='ng/mL',auc_method='linear',c0_method='zero')
av <- function(x,p) x$data$AVAL[x$data$PARAMCD==p]
d <- data.frame(ID='001',TIME=c(-.25,.5,1,2,4,8),CONC=c(0,3,8,6,4,1.5),BLQ=c(1,0,0,0,0,0))
b <- modifyList(s,list(blq_column='BLQ',blq='as_recorded'))
check('actual times C0 zero', {r<-pkapp_nca(d,b);eq(r$data$AVAL,c(8,1,31.5))})
check('predose copy records source', {r<-pkapp_nca(d,modifyList(b,list(c0_method='predose',predose_window_h=.5)));eq(av(r,'AUCLST'),31.5);stopifnot(r$trace$groups[[1]]$c0_source_row==1)})
check('partial AUC and absolute Tmax', {r<-pkapp_nca(d,modifyList(b,list(start=.5)));eq(av(r,'TMAX'),1);eq(av(r,'AUCPART'),30.75);stopifnot(is.na(av(r,'AUCLST')))})
check('nonzero dose origin', {shift<-d;shift$TIME<-shift$TIME+72;r<-pkapp_nca(shift,modifyList(b,list(time_origin=72,start=72)));eq(r$data$AVAL,c(8,1,31.5));eq(r$data$TLAST_QUANT_H,rep(8,3))})
check('terminal BLQ cannot extend AUCLST', {terminal<-rbind(d,data.frame(ID='001',TIME=c(12,24),CONC=.1,BLQ=1));r<-pkapp_nca(terminal,modifyList(b,list(include_aucproc=TRUE)));eq(av(r,'AUCLST'),31.5);eq(av(r,'AUCPROC'),35.9);eq(unique(r$data$TLAST_QUANT_H),8)})
p <- list(op='blq_rules',mode='positional',profile_columns=c('ID','ANALYTE','PERIOD'),concentration='CONC',blq_column='BLQ',time='TIME',mdv_column='MDV',zero_time='pre',pre_rule='zero',first_rule='zero',middle_rule='exclude',last_rule='half_lloq',all_blq_rule='exclude',lloq_value=.2)
raw <- pkapp_read_table('apps/pk-desktop/examples/nca_positional_blq_example.csv')
prepared <- pkapp_prepare(raw,list(p))$data
sp <- modifyList(s,list(groups=c('ANALYTE','PERIOD'),concentration='NCA_CONC',blq_column='NCA_BLQ',mdv_column='NCA_MDV',blq='as_recorded'))
check('lag middle terminal linear reference', eq(av(pkapp_nca(prepared,sp),'AUCLST'),30))
check('lag middle terminal logarithmic reference', {expected<-2+(8-4)/log(8/4)*3+(4-1)/log(4/1)*4;eq(av(pkapp_nca(prepared,modifyList(sp,list(auc_method='lin up/log down'))),'AUCLST'),expected)})
check('CSV roundtrip and reordering retain grouping contract', {f<-tempfile(fileext='.csv');core$pk_write_csv(prepared,f);roundtrip<-pkapp_read_table(f);eq(av(pkapp_nca(roundtrip[nrow(roundtrip):1,],sp),'AUCLST'),30);unlink(f)})
check('prepared identity mismatch rejected', refused(pkapp_nca(prepared,modifyList(sp,list(groups=list())))))
check('prepared time origin mismatch rejected', refused(pkapp_nca(prepared,modifyList(sp,list(time_origin=.25,start=.25)))))
check('post-preparation profile row removal rejected', refused(pkapp_nca(prepared[-4,],sp)))
check('legacy prepared CSV without context rejected', {old<-prepared;old$NCA_BLQ_CONTEXT<-NULL;refused(pkapp_nca(old,sp))})
periods <- data.frame(ID='001',PERIOD=rep(1:2,each=4),TIME=c(-.25,.25,1,3,-.25,.5,1,3),CONC=c('BLQ','4','8','3','BLQ','BLQ','7','4.5'),BLQ=c(1,0,0,0,1,1,0,0))
pp <- modifyList(p,list(profile_columns=c('ID','PERIOD'),mdv_column=''))
ps <- modifyList(sp,list(groups='PERIOD'))
check('two periods independent expected 13.25', {r<-pkapp_nca(pkapp_prepare(periods,list(pp))$data,ps);eq(r$data$AVAL[r$data$PERIOD=='2'&r$data$PARAMCD=='AUCLST'],13.25)})
check('ID-only preparation cannot silently give 15', refused(pkapp_nca(pkapp_prepare(periods,list(modifyList(pp,list(profile_columns='ID'))))$data,ps)))
check('ID cannot be BLQ time', refused(pkapp_prepare(periods,list(modifyList(pp,list(time='ID'))))))
check('single observed peak survives with AUC missing', {r<-pkapp_nca(data.frame(ID='001',TIME=1,CONC=5),s);eq(av(r,'CMAX'),5);eq(av(r,'TMAX'),1);stopifnot(is.na(av(r,'AUCLST')),all(r$data$PROFILE_STATUS!='excluded'))})
check('one sparse subject does not stop other subjects', {x<-rbind(d[c('ID','TIME','CONC')],data.frame(ID='002',TIME=1,CONC=5));r<-pkapp_nca(x,s);eq(r$data$AVAL[r$data$ID=='001'&r$data$PARAMCD=='AUCLST'],31.5);eq(r$data$AVAL[r$data$ID=='002'&r$data$PARAMCD=='CMAX'],5)})
all_blq <- data.frame(ID='001',TIME=c(0,1,2),CONC=0,BLQ=1)
check('all BLQ missing policy reason', {r<-pkapp_nca(all_blq,b);stopifnot(all(is.na(r$data$AVAL)),any(grepl('BLQ',r$data$NCA_EXCLUDE)))})
check('all BLQ explicit zero is policy assignment not observation', {r<-pkapp_nca(all_blq,modifyList(b,list(all_blq_policy='zero')));eq(av(r,'CMAX'),0);eq(av(r,'AUCLST'),0);stopifnot(is.na(av(r,'TMAX')),all(is.na(r$data$TLAST_QUANT_H)),r$data$PARAM_STATUS[r$data$PARAMCD=='AUCLST']=='policy_assigned')})
check('MDV-only samples cannot produce policy zero', {x<-all_blq;x$MDV<-1;r<-pkapp_nca(x,modifyList(b,list(mdv_column='MDV',all_blq_policy='zero')));stopifnot(all(is.na(r$data$AVAL)))})
check('nonBLQ missing sample is not all BLQ', {x<-all_blq;x$BLQ[2]<-0;x$CONC[2]<-NA;r<-pkapp_nca(x,modifyList(b,list(all_blq_policy='zero')));stopifnot(is.na(av(r,'AUCLST')),any(r$data$N_MISSING_CONCENTRATION>0))})
check('missing Cmax time is visible per profile', {x<-d;x$TIME[3]<-NA;r<-pkapp_nca(x,b);eq(av(r,'CMAX'),6);eq(av(r,'TMAX'),2);stopifnot(all(r$data$N_MISSING_TIME==1),all(r$data$PROFILE_STATUS!='ok'),length(r$warnings)>0)})
check('minute ISO and missing date propagate to result counts', {x<-pkapp_read_table('apps/pk-desktop/examples/nca_actual_time_example.csv');x$SAMPLE_DTM[3]<-'2026-11-09';elapsed<-list(op='elapsed_time',sample_column='SAMPLE_DTM',dose_column='DOSE_DTM',utc_offset='+09:00');pb<-modifyList(p,list(time='NCA_TIME_H',flag_convention='y_blank'));z<-pkapp_prepare(x,list(elapsed,pb))$data;r<-pkapp_nca(z,modifyList(sp,list(time='NCA_TIME_H')));eq(av(r,'CMAX'),6);stopifnot(all(r$data$N_MISSING_TIME==1),all(r$data$PROFILE_STATUS!='ok'))})
check('predose QC is optional and does not change values', {x<-d;x$CONC[1]<-9.5;x$BLQ[1]<-0;a<-pkapp_nca(x,modifyList(b,list(c0_method='predose',predose_window_h=.5)));q<-pkapp_nca(x,modifyList(b,list(c0_method='predose',predose_window_h=.5,predose_qc_threshold_pct=5,predose_qc_window_h=.5)));eq(a$data$AVAL,q$data$AVAL);eq(unique(q$data$PREDOSE_QC_PCT),118.75);stopifnot(all(q$data$PREDOSE_QC_STATUS=='exceeds'))})
check('AUC unit order', stopifnot(av(pkapp_nca(d,b),'AUCLST')==31.5,pkapp_nca(d,b)$data$AVALU[3]=='h*ng/mL'))
cat(sprintf('PASS: %d independent scenarios. Numeric reference values are fixed hand calculations.\n',scenarios))
